import csv
import io


def parse_csv(raw_csv: str):
    if not raw_csv:
        return {"columns": [], "rows": []}

    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(max(previous_limit, len(raw_csv)))
        records = list(csv.reader(io.StringIO(raw_csv, newline="")))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    rows = records[1:]
    width = max([6, len(columns)] + [len(row) for row in rows])

    used_names = set(columns)
    while len(columns) < width:
        number = len(columns) + 1
        name = "extra_column_" + str(number)
        while name in used_names:
            number += 1
            name = "extra_column_" + str(number)
        columns.append(name)
        used_names.add(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
